var prep = $('Prep Row').first().json || {};
var company = String(prep.company || '');
var email = String(prep.recipient || '').toLowerCase().trim();
var jd = String(prep.job_description || '');
var score = 0;
var reasons = [];
var kwBlock = false;
// Check 1 (first, cheap, high-signal): email domain vs company domain
var emailDomain = '';
var at = email.indexOf('@');
if (at !== -1) emailDomain = email.slice(at + 1);
var freeProviders = ['gmail.com','yahoo.com','hotmail.com','outlook.com','live.com','aol.com','icloud.com','protonmail.com','mail.com','yandex.com','gmx.com','ymail.com'];
var isFree = false;
for (var i = 0; i < freeProviders.length; i++) { if (emailDomain === freeProviders[i]) { isFree = true; break; } }
var compToken = company.toLowerCase().replace(/[^a-z0-9]/g, '');
var domainCore = (emailDomain.split('.')[0]) || '';
var domainMatches = false;
if (compToken && domainCore && domainCore.length >= 3) { if (compToken.indexOf(domainCore) !== -1 || domainCore.indexOf(compToken.slice(0, 5)) !== -1) domainMatches = true; }
if (isFree) { score += 25; reasons.push('Free-mail domain (' + emailDomain + ') used for company ' + company); }
else if (emailDomain && compToken && !domainMatches) { score += 10; reasons.push('Email domain ' + emailDomain + ' does not obviously match company name'); }
// Description length
var words = jd ? jd.split(/\s+/).filter(function (w) { return w.length > 0; }).length : 0;
if (words > 0 && words < 100) { score += 15; reasons.push('Job description under 100 words (' + words + ')'); }
// Scam keywords -> auto-block
var scamKw = ['training fee','equipment purchase','bank details','bank account number','national id','processing fee','registration fee','pay a deposit','western union','send money','upfront payment','activation fee'];
var hay = (jd + ' ' + company).toLowerCase();
for (var k = 0; k < scamKw.length; k++) { if (hay.indexOf(scamKw[k]) !== -1) { score += 40; reasons.push('Scam keyword detected: ' + scamKw[k]); kwBlock = true; } }
if (score > 100) score = 100;
var decision = 'proceed';
if (score >= 85) decision = 'blocked';
else if (score >= 60) decision = 'flagged';
if (kwBlock) decision = 'blocked';
var reasonText = reasons.length ? reasons.join('; ') : 'No suspicious signals detected';
return [{ json: Object.assign({}, prep, { scam_score: score, scam_decision: decision, scam_reasons: reasonText }) }];

var j = $input.first().json || {};
var cv = String(j.tailored_cv || '');
