function section(text, headers, stops) {
  var lc = text.toLowerCase();
  var start = -1, hlen = 0;
  for (var i = 0; i < headers.length; i++) {
    var idx = lc.indexOf(headers[i]);
    if (idx !== -1) { start = idx; hlen = headers[i].length; break; }
